import{z as B,x as s,o as e,c as p,q as t,j as o,D as E,d as i,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"通胀挂钩","description":"","frontmatter":{"title":"通胀挂钩","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/inflation-linked.md","filePath":"quant/inflation-linked.md","lastUpdated":1791413859000}'),A={name:"quant/inflation-linked.md"};function I(d,a,P,c,m,T){const r=s("Mermaid");return e(),p("div",null,[a[2]||(a[2]=t('<h1 id="通胀挂钩" tabindex="-1">通胀挂钩 <a class="header-anchor" href="#通胀挂钩" aria-label="Permalink to &quot;通胀挂钩&quot;">​</a></h1><div class="epigraph"><p>TIPS 与通胀互换交换的是 CPI 的约定滞后；零息通胀互换的价格定义实际贴现曲线，而不是「预期通胀」四个字。</p><footer>—— Jarrow and Yildirim, Pricing Treasury Inflation Protected Securities and Related Derivatives, Journal of Financial and Quantitative Analysis, 2003</footer></div><p><a href="/quant/weather-power-derivatives">上一课</a>的指数不可交易。通胀挂钩把 CPI 推进利率市场：TIPS、零息与年度通胀互换、通胀 cap/floor。缺口是<strong>实际利率与名义利率的联合建模</strong>，以及公布滞后、季节调整。主干曲线课已有名义 <a href="/quant/curve-bootstrap">Bootstrap</a>。本课不重写名义曲线，只把实际曲线与 BEI（盈亏平衡通胀）接上，后课 caps 再用名义 vol。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>零息通胀互换：到期按 \\(\\mathrm{CPI}_T/\\mathrm{CPI}_0-1\\) 对固定 \\(K\\) 结算（有滞后）。其公平 \\(K\\) 定义一条实际折现与名义折现的比。BEI 是名义与 TIPS 收益率之差，含流动性与通胀风险溢价，<strong>不是</strong>调查预期。问题是衍生品：yoY cap 写在年度通胀率上，需要 CPI 的动态，不是一个 BEI 点。Jarrow–Yildirim 用外汇类比：实际利率当「外国利率」，CPI 当汇率，名义当本币——于是 GK 式的三曲线加上实际与名义的相关。</p><p><span class="marginnote">术语翻译：盈亏平衡通胀（BEI）就是「买名义债和买 TIPS 打平的通胀率」——实际通胀高于它 TIPS 赢，低于它名义债赢。它还打包了流动性差异与通胀风险溢价，所以不等于调查或体感里的「预期」。</span></p><p>滞后与季节：CPI 公布滞后若干月，互换用约定的参考指数。季节调整与未季调指数会让短端 yoY 噪声极大，校准短端 cap 要用指数惯例而不是光滑扩散。</p><h3 id="cpi-不是-gbm-现货" tabindex="-1">CPI 不是 GBM 现货 <a class="header-anchor" href="#cpi-不是-gbm-现货" aria-label="Permalink to &quot;CPI 不是 GBM 现货&quot;">​</a></h3><p>CPI 水平近似积分的通胀率，短期不可交易（除了互换）。库存套利不存在。JY 模型借用 FX 的完整市场叙述，是为了得到闭式，不是因为你可以 Delta 到「CPI 现货」。对冲工具是 TIPS、通胀互换与名义互换，基差（TIPS vs 互换）是一等风险。</p><p><span class="marginnote">直觉类比：把 TIPS 想成「以购买力计价的债券」，CPI 就是购买力这种「货币」的汇率——名义债券是本币债，TIPS 是外币债，通胀互换则是锁定未来汇率的远期合约。JY 模型的外汇类比就是这么搬过来的。</span></p><p><span class="marginnote">常见误区：初学者容易以为能像股票一样「Delta 对冲 CPI 现货」。实际上 CPI 每月才公布一次、短期不可交易，能对冲的只有 TIPS 与互换这些衍生工具，你永远在跟基差和滞后打交道。</span></p>',11)),(e(),o(l,null,{default:E(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20NOM%5B%22%E5%90%8D%E4%B9%89%E5%88%A9%E7%8E%87%20%3D%20%E6%9C%AC%E5%B8%81%E5%88%A9%E7%8E%87%22%5D%20--%3E%20FK%5B%22%E5%A4%96%E6%B1%87%E7%B1%BB%E6%AF%94%E4%B8%89%E4%BB%B6%E5%A5%97%22%5D%0A%20%20REAL%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%20%3D%20%E5%A4%96%E5%9B%BD%E5%88%A9%E7%8E%87%22%5D%20--%3E%20FK%0A%20%20CPI%5B%22CPI%20%E6%B0%B4%E5%B9%B3%20%3D%20%E6%B1%87%E7%8E%87%22%5D%20--%3E%20FK%0A%20%20FK%20--%3E%20BEIS%5B%22%E9%9B%B6%E6%81%AF%E9%80%9A%E8%83%80%E4%BA%92%E6%8D%A2%20%3D%20%E8%BF%9C%E6%9C%9F%E6%B1%87%E7%8E%87%22%5D%0A%20%20FK%20--%3E%20TIPS%5B%22TIPS%20%3D%20%E5%A4%96%E5%B8%81%E9%9B%B6%E6%81%AF%E5%80%BA%22%5D%0A%20%20TIPS%20--%3E%20HEDGE%5B%22%E5%AF%B9%E5%86%B2%E5%B7%A5%E5%85%B7%E9%9D%9E%20CPI%20%E7%8E%B0%E8%B4%A7%22%5D%0A%20%20BEIS%20--%3E%20HEDGE%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">欧洲 HICP 与美国 CPI-U、英国 RPI/CPIH 的定义不同，季节与住房权重不同。曲面不能跨指数拼接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>校准：名义 OIS/政府曲线、TIPS 或通胀互换曲线、可选的通胀 vol（cap/floor 或期权）。JY 或市值模型（例如带微笑的 yoY 市场模型）生成 yoY 率。Cap/floor 用类似名义 cap 的 Black 或移位 Black，后课与负利率衔接——欧元区已出现负通胀与负实际利率。对冲：实际 DV01、名义 DV01、BEI 桶、滞后公布的缺口风险。</p><p><span class="marginnote">数字实例：若合约约定参考指数滞后 3 个月，2026 年 9 月到期结算用的可能是 6 月的 CPI（7 月公布）。这段空窗里通胀怎么跳，互换双方都无法实时调整头寸——这就是「滞后公布的缺口风险」。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>名义零息债 = 实际零息债 × CPI 因子（理想化）。通胀互换把 CPI 因子做成可交易。期权再把 CPI 因子的波动卖掉。相关：名义利率升、通胀升时，实际利率的残差才是 TIPS 的独特风险。JY 把这写成三因子 Vasicek 型；生产更常用市场模型直接对 yoY 率建模，以便校准 cap。</p>',6)),(e(),o(l,null,{default:E(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Nom%5B%22%E5%90%8D%E4%B9%89%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20BEI%5B%22%E7%9B%88%E4%BA%8F%E5%B9%B3%E8%A1%A1%20%E5%90%AB%E6%BA%A2%E4%BB%B7%E4%B8%8E%E6%B5%81%E5%8A%A8%E6%80%A7%22%5D%0A%20%20Real%5B%22%E5%AE%9E%E9%99%85%E6%9B%B2%E7%BA%BF%20TIPS%20%E6%88%96%E4%BA%92%E6%8D%A2%22%5D%20--%3E%20BEI%0A%20%20BEI%20--%3E%20YoY%5B%22%E5%B9%B4%E5%BA%A6%E9%80%9A%E8%83%80%E7%8E%87%E5%8A%A8%E6%80%81%22%5D%0A%20%20YoY%20--%3E%20Cap%5B%22%E9%80%9A%E8%83%80%20cap%20floor%22%5D%0A%20%20Lag%5B%22%E5%85%AC%E5%B8%83%E6%BB%9E%E5%90%8E%E4%B8%8E%E5%AD%A3%E8%8A%82%22%5D%20--%3E%20YoY%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>TIPS 流动性溢价使 BEI 低于互换隐含通胀，拆解必须分开。通缩地板（TIPS 本金地板）是嵌入期权，低通胀时有价值。LDI 与养老金的需求会把实际利率压到与「预期」无关的水平。本课不写宏观预测 CPI；对象是曲线与期权。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>通胀互换定义实际/名义的相对曲线；BEI 不是纯预期。</li><li>yoY cap 需要 CPI 动态；JY 是 FX 类比闭式，对冲仍用 TIPS 与互换。</li><li>滞后、季节、指数定义是合约状态。</li><li>出处：Jarrow and Yildirim, <em>JFQA</em>, 2003。</li></ul>',4))])}const h=B(A,[["render",I]]);export{C as __pageData,h as default};
